  async action(a){if(a==="library"){this.closeCommandPalette();this.closeInvocationHelp();return this.showLibrary()}if(a==="save")return this.save();if(a==="copy-invoke")return this.copyInvocation();if(a==="fullscreen")return this.toggleFullscreen();if(a==="open-palette")return this.openCommandPalette();if(a==="invoke-help")return this.showInvocationHelp();if(a==="toggle-timeline")return this.toggleTimeline();if(a==="undo")return this.undoDo();if(a==="redo")return this.redoDo();if(a==="play"||a==="play2")return this.play();if(a==="preview-reset"||a==="rewind")return this.preview.reset();if(a==="prev-cmd"||a==="step-prev")return this.step(-1);if(a==="next-cmd"||a==="step-next")return this.step(1);if(a==="zoom-in")return this.preview.setZoom(this.preview.zoom+.15);if(a==="zoom-out")return this.preview.setZoom(this.preview.zoom-.15);if(a==="zoom-fit")return this.preview.fit();if(a==="delete-cmd")return this.deleteCmd();if(a==="duplicate-cmd")return this.duplicateCmd();if(a==="import-ruby")return this.openRubyImport();if(a==="import-json")return this.importJsonExternal();if(a==="show-code")return this.showCode();if(a==="tutorials")return this.tutorials();if(a==="about")return this.about();if(a==="shortcuts")return this.shortcuts();if(a==="duplicate-scene")return this.duplicateScene();if(a==="delete-scene")return this.deleteScene();if(a==="scene-props")return this.sceneProps()}
