  onKey(e){
    if(!this.root.isConnected)return;
    if(!this.fullscreenActive&&this.host?.getClientRects&&this.host.getClientRects().length===0)return;
    if(e.key==="F11"){e.preventDefault();e.stopPropagation();this.toggleFullscreen();return}
    if(this.manualCopyOverlay){if(e.key==="Escape"){e.preventDefault();this.manualCopyOverlay.remove();this.manualCopyOverlay=null}return}
    if(this.codeOverlay){if(e.key==="Escape"){e.preventDefault();this.codeOverlay.remove();this.codeOverlay=null}return}
    if(this.helpOverlay){if(e.key==="Escape"){e.preventDefault();this.closeInvocationHelp()}return}
    if(this.paletteOverlay){if(e.key==="Escape"){e.preventDefault();this.closeCommandPalette()}return}
    if(this.fullscreenActive&&e.key==="Escape"){e.preventDefault();e.stopPropagation();this.exitFullscreen();return}
    if(this.view!=="editor")return;const tag=(e.target?.tagName||"").toLowerCase(),editing=["input","textarea","select"].includes(tag);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();this.openCommandPalette();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();this.save();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="z"){e.preventDefault();e.shiftKey?this.redoDo():this.undoDo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="y"){e.preventDefault();this.redoDo();return}if(editing)return;if(this.preview.state.confirm){if(e.key==="ArrowLeft"||e.key==="ArrowRight"){e.preventDefault();this.preview.selectConfirmation(1);return}if(e.key==="Escape"){e.preventDefault();this.preview.state.confirm=null;return}if(e.key==="Enter"||e.code==="Space"){e.preventDefault();this.preview.continue();return}e.preventDefault();return}if(this.preview.state.naming){if(this.preview.nameKey(e.key)){e.preventDefault();return}}if(this.preview.state.treatment&&(e.key==="ArrowLeft"||e.key==="ArrowRight")){e.preventDefault();this.preview.changeTreatment(e.key==="ArrowLeft"?-1:1);return}if(e.code==="Space"||e.key==="Enter"||e.code==="KeyC"){e.preventDefault();this.preview.continue();if(!this._playing)this.play()}if(e.key==="Delete"){e.preventDefault();this.deleteCmd()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="d"){e.preventDefault();this.duplicateCmd()}}
